        <td><Card render={({ active }) => active ? <b>Active {Object.entries(data).reduce((nodes, [entryKey, value]) => nodes.concat(<p key={entryKey}>Entry {entryKey}: {value}</p>), [])}</b> : <Value>{row.raw}</Value>} /></td>
      </tr>{row.children?.map(child => <tr key={child.id}><td colSpan={index + 1}>Nested {child.name}</td></tr>)}</Fragment>)}
    </tbody></table>);
